// Code generated by lean-go format from the udp spec; DO NOT EDIT.

package udp

import (
	"bytes"
	"encoding/binary"
	"errors"
	"io"
	"math"
	"math/rand/v2"
	"testing"
)

// referenceDecoder is an independent decoder for the format, registered by a
// hand-written test file of this package in an init function. ok reports
// whether the bytes are a valid header.
type referenceDecoder struct {
	name   string
	decode func(data []byte) (h Header, ok bool)
}

var referenceDecoders []referenceDecoder

var _ = binary.BigEndian // not every format has multi-byte words

// specParse reads the spec directly with encoding/binary. It shares no code
// with the extracted parser and checks in the same order.
func specParse(data []byte) (Header, Reason) {
	if len(data) < HeaderSize {
		return Header{}, ReasonTruncated
	}
	var h Header
	w0 := uint64(binary.BigEndian.Uint16(data[0:2]))
	vSrcPort := w0
	h.SrcPort = uint16(vSrcPort)
	w1 := uint64(binary.BigEndian.Uint16(data[2:4]))
	vDstPort := w1
	h.DstPort = uint16(vDstPort)
	w2 := uint64(binary.BigEndian.Uint16(data[4:6]))
	vLength := w2
	if vLength < 8 {
		return Header{}, ReasonLengthTooSmall
	}
	h.Length = uint16(vLength)
	w3 := uint64(binary.BigEndian.Uint16(data[6:8]))
	vChecksum := w3
	h.Checksum = uint16(vChecksum)
	return h, 0
}

func specValidate(h Header) Reason {
	if uint64(h.Length) < 8 {
		return ReasonLengthTooSmall
	}
	return 0
}

func specSerialize(h Header) [HeaderSize]byte {
	var raw [HeaderSize]byte
	binary.BigEndian.PutUint16(raw[0:2], uint16(uint64(h.SrcPort)<<0))
	binary.BigEndian.PutUint16(raw[2:4], uint16(uint64(h.DstPort)<<0))
	binary.BigEndian.PutUint16(raw[4:6], uint16(uint64(h.Length)<<0))
	binary.BigEndian.PutUint16(raw[6:8], uint16(uint64(h.Checksum)<<0))
	return raw
}

func specPayloadLength(h Header) uint64 {
	return uint64(h.Length) - 8
}

func pick(r *rand.Rand, lo, hi uint64) uint64 {
	switch r.IntN(4) {
	case 0:
		return lo
	case 1:
		return hi
	}
	if lo == 0 && hi == math.MaxUint64 {
		return r.Uint64()
	}
	return lo + r.Uint64N(hi-lo+1)
}

// randomHeader returns a valid header, biased towards boundary values.
func randomHeader(r *rand.Rand) Header {
	var h Header
	h.SrcPort = uint16(pick(r, 0, 65535))
	h.DstPort = uint16(pick(r, 0, 65535))
	h.Length = uint16(pick(r, 8, 65535))
	h.Checksum = uint16(pick(r, 0, 65535))
	return h
}

// anyHeader returns arbitrary field values, mostly invalid ones near the limits.
func anyHeader(r *rand.Rand) Header {
	var h Header
	h.SrcPort = uint16(pick(r, 0, 65535))
	h.DstPort = uint16(pick(r, 0, 65535))
	h.Length = uint16(pick(r, 0, 65535))
	h.Checksum = uint16(pick(r, 0, 65535))
	return h
}

func reasonOf(t *testing.T, err error) Reason {
	t.Helper()
	if err == nil {
		return 0
	}
	var e *Error
	if !errors.As(err, &e) {
		t.Fatalf("unexpected error type %T: %v", err, err)
	}
	return e.Reason
}

// inputs yields valid encodings, single-bit mutations of them and random bytes.
func inputs(r *rand.Rand, n int, yield func(data []byte)) {
	for i := 0; i < n; i++ {
		raw := specSerialize(randomHeader(r))
		data := raw[:]
		switch i % 4 {
		case 1:
			bit := r.IntN(8 * HeaderSize)
			data[bit/8] ^= 1 << (bit % 8)
		case 2:
			for j := range data {
				data[j] = byte(r.Uint32())
			}
		case 3:
			data[r.IntN(HeaderSize)] = byte(r.Uint32())
		}
		yield(append([]byte(nil), data...))
	}
}

func TestRoundTripValidHeaders(t *testing.T) {
	r := rand.New(rand.NewPCG(1, 3))
	for i := 0; i < 5000; i++ {
		h := randomHeader(r)
		if err := Validate(h); err != nil {
			t.Fatalf("Validate(%+v) = %v", h, err)
		}
		if reason := specValidate(h); reason != 0 {
			t.Fatalf("specValidate(%+v) = %v", h, reason)
		}
		enc, err := AppendSerialize(nil, h)
		if err != nil {
			t.Fatalf("AppendSerialize(%+v): %v", h, err)
		}
		if want := specSerialize(h); !bytes.Equal(enc, want[:]) {
			t.Fatalf("AppendSerialize(%+v) = %x, spec says %x", h, enc, want)
		}
		data := enc
		size := specPayloadLength(h)
		if size > 1<<16 {
			// Too large to materialize: the header alone must ask for the payload.
			_, _, _, err := Parse(data)
			var e *Error
			if !errors.As(err, &e) || e.Reason != ReasonPayloadTruncated || e.Missing != size {
				t.Fatalf("Parse(header of %+v) = %v, want %d payload bytes missing", h, err, size)
			}
			continue
		}
		data = append(data, bytes.Repeat([]byte{0xa5}, int(size))...)
		data = append(data, 1, 2, 3)
		got, n, payload, err := Parse(data)
		if err != nil || got != h {
			t.Fatalf("Parse(%x) = %+v, %v; want %+v", data, got, err, h)
		}
		if n != HeaderSize+int(size) || len(payload) != int(size) || cap(payload) != len(payload) {
			t.Fatalf("Parse(%x) consumed %d with payload %d/%d, want %d", data, n, len(payload), cap(payload), HeaderSize+int(size))
		}
	}
}

func TestParseMatchesSpec(t *testing.T) {
	r := rand.New(rand.NewPCG(2, 3))
	inputs(r, 20000, func(data []byte) {
		want, wantReason := specParse(data)
		got, reason := parseHeaderOnly(t, data)
		if reason != wantReason || got != want {
			t.Fatalf("Parse(%x) = %+v, %v; spec says %+v, %v", data, got, reason, want, wantReason)
		}
		if reason != 0 {
			return
		}
		enc, err := AppendSerialize(nil, got)
		if err != nil || !bytes.Equal(enc, data[:HeaderSize]) {
			t.Fatalf("serialize(parse(%x)) = %x, %v", data, enc, err)
		}
	})
}

// parseHeaderOnly parses data and reports the header decision alone.
func parseHeaderOnly(t *testing.T, data []byte) (Header, Reason) {
	t.Helper()
	got, n, payload, err := Parse(data)
	reason := reasonOf(t, err)
	if reason == ReasonPayloadTruncated {
		var e *Error
		errors.As(err, &e)
		if !errors.Is(err, io.ErrUnexpectedEOF) {
			t.Fatalf("payload truncation does not match io.ErrUnexpectedEOF")
		}
		// The header itself was accepted: recover it from the reference.
		h, _ := specParse(data)
		if uint64(e.Missing) != specPayloadLength(h)-uint64(len(data)-HeaderSize) {
			t.Fatalf("Parse(%x) missing %d", data, e.Missing)
		}
		return h, 0
	}
	if reason == 0 && (n < HeaderSize || len(payload) != n-HeaderSize) {
		t.Fatalf("Parse(%x) consumed %d with payload %d", data, n, len(payload))
	}
	return got, reason
}

func TestValidateMatchesSpec(t *testing.T) {
	r := rand.New(rand.NewPCG(3, 3))
	for i := 0; i < 20000; i++ {
		h := anyHeader(r)
		if i%2 == 0 {
			h = randomHeader(r)
		}
		got := reasonOf(t, Validate(h))
		if want := specValidate(h); got != want {
			t.Fatalf("Validate(%+v) = %v, spec says %v", h, got, want)
		}
		dst := make([]byte, 3, 64)
		copy(dst[:cap(dst)], bytes.Repeat([]byte{0x5a}, cap(dst)))
		out, err := AppendSerialize(dst, h)
		if got != 0 {
			if err == nil || len(out) != 3 || !bytes.Equal(dst[:cap(dst)], bytes.Repeat([]byte{0x5a}, cap(dst))) {
				t.Fatalf("AppendSerialize(invalid %+v) = %x, %v; or wrote to dst", h, out, err)
			}
		} else if err != nil || !bytes.Equal(out[:3], []byte{0x5a, 0x5a, 0x5a}) {
			t.Fatalf("AppendSerialize(%+v) = %x, %v", h, out, err)
		}
	}
}

func TestTruncatedInput(t *testing.T) {
	raw := specSerialize(randomHeader(rand.New(rand.NewPCG(4, 4))))
	for size := 0; size < HeaderSize; size++ {
		data := raw[:size]
		got, n, payload, err := Parse(data)
		if payload != nil {
			t.Fatal("payload on error")
		}
		var e *Error
		if !errors.As(err, &e) || e.Reason != ReasonTruncated || e.Missing != uint64(HeaderSize-size) ||
			!errors.Is(err, io.ErrUnexpectedEOF) || n != 0 || got != (Header{}) {
			t.Fatalf("Parse(%d bytes) = %+v, %d, %v", size, got, n, err)
		}
	}
}

func TestReferenceDecoders(t *testing.T) {
	if len(referenceDecoders) == 0 {
		t.Skip("no hand-written reference decoder registered for this format")
	}
	r := rand.New(rand.NewPCG(5, 3))
	inputs(r, 20000, func(data []byte) {
		got, reason := parseHeaderOnly(t, data)
		for _, ref := range referenceDecoders {
			want, ok := ref.decode(data)
			if ok != (reason == 0) || (ok && want != got) {
				t.Fatalf("%s: decode(%x) = %+v, %v; Parse gives %+v, %v", ref.name, data, want, ok, got, reason)
			}
		}
	})
}

func FuzzParse(f *testing.F) {
	r := rand.New(rand.NewPCG(6, 3))
	for i := 0; i < 8; i++ {
		raw := specSerialize(randomHeader(r))
		f.Add(raw[:])
	}
	f.Add([]byte{})
	f.Add(bytes.Repeat([]byte{0xff}, HeaderSize+3))
	f.Fuzz(func(t *testing.T, data []byte) {
		before := append([]byte(nil), data...)
		got, reason := parseHeaderOnly(t, data)
		if !bytes.Equal(before, data) {
			t.Fatal("Parse modified its input")
		}
		want, wantReason := specParse(data)
		if reason != wantReason || got != want {
			t.Fatalf("Parse(%x) = %+v, %v; spec says %+v, %v", data, got, reason, want, wantReason)
		}
		if reason == 0 {
			enc, err := AppendSerialize(nil, got)
			if err != nil || !bytes.Equal(enc, data[:HeaderSize]) {
				t.Fatalf("serialize(parse(%x)) = %x, %v", data, enc, err)
			}
		}
	})
}

func FuzzRoundTrip(f *testing.F) {
	f.Add(uint64(0), uint64(0))
	f.Add(uint64(1), uint64(math.MaxUint64))
	f.Fuzz(func(t *testing.T, a, b uint64) {
		r := rand.New(rand.NewPCG(a, b))
		h := randomHeader(r)
		enc, err := AppendSerialize(nil, h)
		if err != nil {
			t.Fatalf("AppendSerialize(%+v): %v", h, err)
		}
		got, reason := parseHeaderOnly(t, enc)
		if reason != 0 || got != h {
			t.Fatalf("Parse(AppendSerialize(%+v)) = %+v, %v", h, got, reason)
		}
	})
}

func TestPayload(t *testing.T) {
	r := rand.New(rand.NewPCG(7, 3))
	for i := 0; i < 2000; i++ {
		h := randomHeader(r)
		size := specPayloadLength(h)
		if size > 1<<12 {
			continue
		}
		enc, err := AppendSerialize(nil, h)
		if err != nil {
			t.Fatal(err)
		}
		if got, err := PayloadLength(h); err != nil || uint64(got) != size {
			t.Fatalf("PayloadLength(%+v) = %d, %v; want %d", h, got, err, size)
		}
		body := make([]byte, size+2)
		for j := range body {
			body[j] = byte(j)
		}
		avails := []uint64{0, size / 2, size, size + 1, size + 2}
		if size > 0 {
			avails = append(avails, size-1)
		}
		for _, avail := range avails {
			data := append(append([]byte(nil), enc...), body[:avail]...)
			got, n, payload, err := Parse(data)
			if avail < size {
				var e *Error
				if !errors.As(err, &e) || e.Reason != ReasonPayloadTruncated || e.Missing != size-avail || n != 0 || payload != nil {
					t.Fatalf("Parse with %d of %d payload bytes = %v, %d", avail, size, err, n)
				}
				continue
			}
			if err != nil || got != h || n != HeaderSize+int(size) || !bytes.Equal(payload, body[:size]) || cap(payload) != len(payload) {
				t.Fatalf("Parse with %d of %d payload bytes = %v, %d, %x", avail, size, err, n, payload)
			}
			payload = append(payload, 0xee)
			if !bytes.Equal(data[:len(enc)+int(avail)], append(append([]byte(nil), enc...), body[:avail]...)) {
				t.Fatal("appending to the payload changed the input")
			}
		}
		frame, err := AppendFrame([]byte{9}, h, body[:size])
		if err != nil || !bytes.Equal(frame, append(append([]byte{9}, enc...), body[:size]...)) {
			t.Fatalf("AppendFrame(%+v) = %x, %v", h, frame, err)
		}
		if _, err := AppendFrame(nil, h, body[:size+1]); reasonOf(t, err) != ReasonPayloadLengthMismatch {
			t.Fatalf("AppendFrame with a wrong length: %v", err)
		}
		// The payload may overlap the destination's spare capacity.
		buf := make([]byte, 0, 2*(HeaderSize+int(size))+8)
		buf = append(buf, 7)
		src := buf[1 : 1+int(size)]
		copy(src, body[:size])
		out, err := AppendFrame(buf, h, src)
		if err != nil || !bytes.Equal(out, append(append([]byte{7}, enc...), body[:size]...)) {
			t.Fatalf("overlapping AppendFrame(%+v) = %x, %v", h, out, err)
		}
	}
}
